      setManualStyle(s);
      setManualOverride(true);
      setCurrentStyle(s);
      applyDataStyle(s);
    },
    // 恢复自动映射
    restoreAuto: (agentType?: string) => {
      setManualOverride(false);
      updateStyle(agentType);
    },
